B: Exponential

 ֤ 1 Ҏ্X ҎԼͷ੔਺x ʹରͯ͠ɺexpox := x ͕΂͖৐਺͔ ͱ͍͏ਅِ஋Λߟ͑·͢ɻ͜Ε͕ਖ਼͘͠ܭ
ࢉͰ͖Ε͹౴͑͸ ٻ ·Γ·͢ɻ
  1 Ҏ্ͷ੔਺b ͱɺ 2 Ҏ্ͷ੔਺p શͯͷϖΞʹରͯ͠ x := bp Λܭࢉ͠ɺx ͕ 1 Ҏ্X ҎԼͳΒ expox
Λ true ʹॻ͖׵͑Δ ͱ͍͏͜ͱΛ͢ΔͱఆٛΑΓਖ਼͘͠ٻ·Γ·͕͢ɺ౰વ͢΂ͯͷ੔਺ͷϖΞΛࢼ͢ͷ͸

ෆՄೳͰ͢ɻ

 ·ͣɺ b ͱͯ͠ࢼ͢΂͖஋͸ 1 Ҏ্X ҎԼͷ੔਺ͷΈͰΑ͍Ͱ͢ (ͳͥͳΒɺ b > X ͳΒ೚ҙͷ p >= 2
ʹରͯ͠ bp > X ͔ͩΒ౴͑ʹӨڹΛٴ΅͞ͳ͍)ɻ

 ಉ༷ʹɺ p ͱͯ͠ ࢼ ͢΂͖஋͸ (ͱͯ΋ ࡶ ʹ ݟ ੵ΋ͬͯ΋) 2 Ҏ্X ҎԼͷ੔਺ͷΈͰे෼Ͱ͢ɻΑͬͯ
ೋॏϧʔϓͰ b, p ͷશͯͷϖΞΛࢼ͢͜ͱͰ expox ͕ਖ਼͘͠ٻ·Γ·͢ɻ ࣌ؒܭࢉྔ͸ O(X2) Ͱ͢ɻ
 ͔͠͠ɺΦʔόʔϑϩʔΛ ى͜͞ͳ͍ͨΊʹ΋ҎԼͷํ๏͕ྑ͍ͱࢥ͍·͢ɻ

 ֤ b ʹରͯ͠ɺp = 2, 3, .. ͱॱ൪ʹ, expobp Λ true ʹॻ͖ ׵ ͍͖͑ͯ·͢ɻ͜͜Ͱɺ΋͠ ࠓ ௐ΂͍ͯΔ஋
bk ͕ X ΑΓେ͖͔ͬͨΒɺk Ҏ ߱ ͷ஋͸ p ͱͯ͠ ߟ ͑Δඞཁ͕͋Γ·ͤΜɻैͬͯͦ͜Ͱ p ͷϧʔϓΛଧ

ͪ੾ͬͯྑ͍Ͱ͢ɻͨͩ͠ b = 1 ͷ࣌ʹ͸͜ͷ৚݅Ͱͷଧͪ੾Γ͸ൃੜ͠ͳ͍ͷͰ஫ҙ͍ͯͩ͘͠͞ɻ

#include <bits/stdc ++.h>
using namespace std;


                                             1

int main (){
         int X;
         cin >>X;
         vector <bool > expo(X+1);


         expo [1] = 1;
        for(int b=2;b<=X;b++){
                  int v = b*b;
                while(v<=X){
                         expo[v] = 1;
                             v *= b;
                   }
          }
        for(int i=X;i >=1;i--) if(expo[i]){
                  cout <<i<<endl;
                 return 0;
          }
}
